#version 300 es
precision mediump float;

uniform sampler2D u_texture; 
uniform sampler2D u_gradientTexture; // gradient
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec4 color = texture(u_texture, vUv);

  float brightness = dot(color.rgb, vec3(0.299, 0.587, 0.114));

  vec4 gradientColor = texture(u_gradientTexture, vec2(brightness, 0.5));

  fragColor = vec4(gradientColor.rgb, 1.0);
}

#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_texture_1;
uniform sampler2D u_texture_2;

void main() {
    fragColor = clamp(
        texture(u_texture_1, vUv) / (texture(u_texture_2, vUv) + 0.001),
        vec4(0.),
        vec4(1.)
    );
}

#version 300 es
precision mediump float;

uniform vec2 u_resolution; // resolution

uniform sampler2D u_channel0;

uniform float u_radius;    // [0.0, 1, 0.01]
uniform float u_threshold; // [0.001, 2, 0.5]
uniform float u_sample_count; // [1, 256, 64]

in vec2 vUv;
out vec4 fragColor;

void main() {

    float computed_threshold_value = u_threshold * 100.0;
    float aspect = u_resolution.x / u_resolution.y;

    mat2 rot = mat2(-0.737, -0.676, 0.676, -0.737);
    vec2 p_iso = vec2(u_radius / (sqrt(u_sample_count)), 0.0);

    float N = 0.0;

    vec4 O = vec4(0.0);
    for (float i = 1.0; i < u_sample_count; i += 1.0) {
        p_iso = rot * p_iso;

        vec2 p_uv = vec2(p_iso.x / aspect, p_iso.y);
        O += exp(texture(u_channel0, vUv + p_uv * sqrt(i)) * computed_threshold_value);
        N += 1.0;
    }

    O = (log(O) - log(N));
    O /= computed_threshold_value;
    fragColor = O;
}

